n = 50
num_list = [10, 4, 23, 6, 18, 27, 47]
found = False  # 一旦找到，found就会变成True。

for n1 in num_list:
    for n2 in num_list:
        if(n1 + n2 == n):
            found = True  # 找到后，设置found为True
            break  # break 语句，跳出内循环
    if found:
        print(n1, n2) # 输出配对
        break  # bear语句。跳出外循环

num_list = list(range(0, 10))

for num in num_list:
    if num == 3 or num == 6 or num == 8:
        continue
    print(num)
